<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {PositionCompetition,PositionResult} from '@torneos/shared';
import SportTabs from './SportTabs.vue';
import Icon from './Icon.vue';

type Slot={slot_code:string;entry_id:string|null;team_id:string|null;team_name:string|null;color:string|null;has_shield:boolean};
type Team={entry_id:string;team_id:string;team_name:string;color:string|null;has_shield:boolean};
type Game={code:string;stage:'groups'|'quarterfinal'|'quadrangular';sporting_round:string;jornada_no:number|null;planned_date:string|null;home_ref:string;away_ref:string};
export type PublicDraw={tournament_id:string;tournament_name:string;public_slug:string|null;has_emblem:boolean;category_id:string;category_name:string;revision:number;snapshot:{blueprint:{name:string;opening_first_date:string;opening_second_date:string};slots:Slot[];teams?:Team[];games:Game[]}};
type Competition={available:boolean;competition?:PositionCompetition;results?:PositionResult[];matches?:Array<{code:string;match_id:string}>;players?:Array<{registrationId:string;entryId:string;goals:number;name:string}>;defense?:Array<{entryId:string;played:number;goalsAgainst:number}>;titleExtra?:{decision:'no_extra'|'extra';matchId:string|null;homeEntryId:string|null;awayEntryId:string|null;score:{home:number;away:number;homePenalties:number;awayPenalties:number}|null;winnerEntryId:string|null}|null};
type MatchDetail={id:string;home_name:string;away_name:string;match_date:string;match_time:string;result:{score:{home:number;away:number};shootout:{home:number;away:number};events:Array<{id:string;kind:string;period:string|null;name:string;cardLabel:string|null;side:string}>}|null};
const props=defineProps<{organization:{id:string;name:string;logo_id?:string|null}|null;draws:PublicDraw[];selectedTournamentId:string;resultsRevision:number}>();
const emit=defineEmits<{navigate:[path:string]}>();
const current=computed(()=>props.draws.find(item=>item.tournament_id===props.selectedTournamentId)||props.draws[0]);
const tab=ref('matches'),fixtureTab=ref('dates'),classificationTab=ref('groups'),groupTab=ref<'A'|'B'>('A');
const selectedRound=ref('F1'),selectedDay=ref(0),selectorOpen=ref(!props.selectedTournamentId);
const competition=ref<Competition|null>(null),error=ref(''),selectedMatch=ref<MatchDetail|null>(null),selectedGame=ref<Game|null>(null),selectedTeam=ref<Team|null>(null),teamPlayers=ref<Array<{name:string}>>([]),teamLoading=ref(false);
let epoch=0;
async function loadCompetition(){const category=current.value?.category_id,organization=props.organization?.id,currentEpoch=++epoch;competition.value=null;error.value='';if(!category||!organization)return;try{const response=await fetch(`/api/v1/public/organizations/${organization}/draws/${category}/competition`);if(!response.ok)throw new Error();const data=await response.json() as Competition;if(currentEpoch===epoch)competition.value=data;}catch{if(currentEpoch===epoch)error.value='No se pudieron cargar los resultados.';}}
watch(()=>[current.value?.category_id,props.organization?.id,current.value?.revision,props.resultsRevision],loadCompetition,{immediate:true});
watch(()=>current.value?.tournament_id,()=>{selectedRound.value='F1';selectedDay.value=days.value[0]??0;selectedMatch.value=null;selectedGame.value=null;selectedTeam.value=null;});
const slots=computed(()=>new Map((current.value?.snapshot.slots||[]).map(slot=>[slot.slot_code,slot])));
const teams=computed<Team[]>(()=>current.value?.snapshot.teams||current.value?.snapshot.slots.filter(slot=>slot.entry_id&&slot.team_id&&slot.team_name).map(slot=>({entry_id:slot.entry_id!,team_id:slot.team_id!,team_name:slot.team_name!,color:slot.color,has_shield:slot.has_shield}))||[]);
const byEntry=computed(()=>new Map(teams.value.map(team=>[team.entry_id,team])));
const allGames=computed(()=>(current.value?.snapshot.games||[]).map((game,index)=>({...game,index})));
const rounds=computed(()=>[...new Set(allGames.value.map(game=>game.sporting_round))]);
const roundGames=computed(()=>allGames.value.filter(game=>game.sporting_round===selectedRound.value));
const pendingOpening=computed(()=>allGames.value.filter(game=>game.jornada_no===null));
const days=computed(()=>[...(pendingOpening.value.length?[0]:[]),...[...new Set(allGames.value.map(game=>game.jornada_no).filter((day):day is number=>day!==null))].sort((a,b)=>a-b)]);
watch(days,available=>{if(!available.includes(selectedDay.value))selectedDay.value=available[0]??0;},{immediate:true});
const dayGames=computed(()=>allGames.value.filter(game=>selectedDay.value===0?game.jornada_no===null:game.jornada_no===selectedDay.value));
const nearbyDays=computed(()=>{if(selectedDay.value<3||!dayGames.value.length)return [];const following=days.value.filter(day=>day>selectedDay.value&&allGames.value.some(game=>game.jornada_no===day)).slice(0,selectedDay.value>=10?2:1);return following.length?following:days.value.filter(day=>day===selectedDay.value-1&&allGames.value.some(game=>game.jornada_no===day));});
const matchSections=computed(()=>days.value.map(day=>({day,games:allGames.value.filter(game=>day===0?game.jornada_no===null:game.jornada_no===day)})).filter(section=>section.games.length));
const results=computed(()=>new Map((competition.value?.results||[]).map(result=>[result.code,result])));
const matches=computed(()=>new Map((competition.value?.matches||[]).map(match=>[match.code,match.match_id])));
const scorers=computed(()=>[...(competition.value?.players||[])].filter(player=>player.goals>0).sort((a,b)=>b.goals-a.goals||a.name.localeCompare(b.name)));
const defense=computed(()=>[...(competition.value?.defense||[])].filter(team=>team.played>0).sort((a,b)=>a.goalsAgainst-b.goalsAgainst||b.played-a.played));
function crest(team:Team|Slot|undefined){return team?.has_shield&&team.team_id?`/api/v1/public/organizations/${props.organization?.id}/draws/teams/${team.team_id}/shield`:null;}
function refName(code:string){const assigned=slots.value.get(code)?.team_name;if(assigned)return assigned;if(/^[1-4][AB]$/.test(code))return `${code[0]}.º Grupo ${code[1]}`;if(/^S[1-4]$/.test(code))return `${code[1]}.º entre ganadores`;return code;}
function gameName(game:Game,side:'home'|'away'){const id=competition.value?.competition?.participants[game.code]?.[side==='home'?'homeEntryId':'awayEntryId'];return id?byEntry.value.get(id)?.team_name||'Por definir':refName(side==='home'?game.home_ref:game.away_ref);}
function gameTeam(game:Game,side:'home'|'away'){const id=competition.value?.competition?.participants[game.code]?.[side==='home'?'homeEntryId':'awayEntryId'];return id?byEntry.value.get(id):slots.value.get(side==='home'?game.home_ref:game.away_ref);}
function result(game:Game){const score=results.value.get(game.code);return score?`${score.homeGoals} : ${score.awayGoals}`:'–';}
function date(value:string|null){if(!value)return 'Por definir';const [year,month,day]=value.slice(0,10).split('-');return `${day}/${month}/${year}`;}
function gameDate(game:Game){return game.planned_date?date(game.planned_date):game.sporting_round==='F1'?`${date(current.value?.snapshot.blueprint.opening_first_date||null)} / ${date(current.value?.snapshot.blueprint.opening_second_date||null)}`:'Por definir';}
function roundLabel(value:string){return /^F\d+$/.test(value)?`F${value.slice(1)}`:value==='Cuartos'?'Cuartos':value.replace('Cuadrangular ','Final ');}
function roundTitle(value:string){return /^F\d+$/.test(value)?`Fecha ${value.slice(1)}`:value.replace('Cuadrangular ','Final ');}
function dayTitle(value:number){return value===0?'J1/J2 por definir':`Jornada ${value}`;}
function dayDate(value:number){if(value===0)return `${date(current.value?.snapshot.blueprint.opening_first_date||null)} / ${date(current.value?.snapshot.blueprint.opening_second_date||null)}`;if(value===1)return date(current.value?.snapshot.blueprint.opening_first_date||null);if(value===2)return date(current.value?.snapshot.blueprint.opening_second_date||null);return date(allGames.value.find(game=>game.jornada_no===value)?.planned_date||null);}
function rows(table:NonNullable<PositionCompetition['final']>){return table.groups.flatMap(group=>group.teamIds.map(id=>({position:group.position,id,unresolved:group.unresolved,stats:table.totals.find(item=>item.teamId===id)})));}
function chooseTournament(id:string){selectorOpen.value=false;tab.value='matches';emit('navigate',`publico/${props.organization?.id}/${id}`);}
async function openMatch(code:string){const game=allGames.value.find(item=>item.code===code);if(!game)return;selectedGame.value=game;selectedMatch.value=null;const id=matches.value.get(code),organization=props.organization?.id,category=current.value?.category_id;if(!id||!organization)return;try{const response=await fetch(`/api/v1/public/organizations/${organization}/fixture`);if(!response.ok)return;const days=await response.json() as Array<{matches:MatchDetail[]}>;if(selectedGame.value?.code===code&&props.organization?.id===organization&&current.value?.category_id===category)selectedMatch.value=days.flatMap(day=>day.matches).find(match=>match.id===id)||null;}catch{/* El cruce planificado sigue disponible. */}}
async function openTeam(team:Team){selectedTeam.value=team;teamPlayers.value=[];teamLoading.value=true;const organization=props.organization?.id,category=current.value?.category_id;if(!organization||!category){teamLoading.value=false;return;}try{const response=await fetch(`/api/v1/public/organizations/${organization}/draws/${category}/teams/${team.entry_id}/players`);if(response.ok){const players=await response.json() as Array<{name:string}>;if(selectedTeam.value?.entry_id===team.entry_id&&props.organization?.id===organization&&current.value?.category_id===category)teamPlayers.value=players;}}catch{/* La ficha permanece accesible sin jugadores. */}finally{if(selectedTeam.value?.entry_id===team.entry_id)teamLoading.value=false;}}
function closeMatch(){selectedMatch.value=null;selectedGame.value=null;}
</script>

<template>
  <div class="position-public">
    <header v-if="!selectedMatch&&!selectedGame&&!selectedTeam" class="public-header"><div class="public-header-top"><button type="button" class="public-back" aria-label="Volver a organizaciones" @click="emit('navigate','publico')"><Icon name="back" /></button><img v-if="organization?.logo_id" :src="`/api/v1/public/organizations/${organization.id}/logo`" alt="" class="public-org-logo"><small>{{ organization?.name }}</small></div><button type="button" :aria-expanded="selectorOpen" @click="selectorOpen=!selectorOpen"><img v-if="current?.has_emblem && organization" :src="`/api/v1/public/organizations/${organization.id}/tournaments/${current.tournament_id}/emblem`" alt="" class="public-cup-logo"><Icon v-else name="trophy"/><strong>{{ current?.tournament_name||'Elegí un torneo' }}</strong><Icon name="chevron"/></button></header>
    <div v-if="!selectedMatch&&!selectedGame&&!selectedTeam&&selectorOpen" class="public-selector"><button v-for="draw in draws" :key="draw.tournament_id" type="button" @click="chooseTournament(draw.tournament_id)">{{ draw.tournament_name }}<Icon name="arrow"/></button></div>
    <template v-else-if="current&&!selectedMatch&&!selectedGame&&!selectedTeam">
      <SportTabs v-model="tab" :tabs="[{key:'matches',label:'Partidos',icon:'ball'},{key:'fixture',label:'Fixture',icon:'calendar'},{key:'classification',label:'Clasificación',icon:'chart'},{key:'scorers',label:'Goleadores',icon:'ball'},{key:'defense',label:'Valla',icon:'shield'},{key:'teams',label:'Equipos',icon:'users'}]" id="public-position" />
      <main class="public-body">
        <div v-if="error" class="public-error" role="alert">{{ error }} <button type="button" @click="loadCompetition">Reintentar</button></div>
        <section v-if="tab==='matches'" id="public-position-matches-panel" role="tabpanel" aria-labelledby="public-position-matches-tab">
          <div v-for="section in matchSections" :key="section.day" class="public-match-section"><h2>{{ dayTitle(section.day) }} <small>{{ dayDate(section.day) }}</small></h2><button v-for="game in section.games" :key="game.code" type="button" class="public-game" :aria-label="`Abrir ${gameName(game,'home')} contra ${gameName(game,'away')}`" @click="openMatch(game.code)"><small>{{ roundTitle(game.sporting_round) }}</small><div class="public-game-sides"><span><img v-if="crest(gameTeam(game,'home'))" :src="crest(gameTeam(game,'home'))!" alt=""><b v-else>{{ game.home_ref[0] }}</b><strong>{{ gameName(game,'home') }}</strong></span><em>{{ result(game) }}</em><span class="away"><img v-if="crest(gameTeam(game,'away'))" :src="crest(gameTeam(game,'away'))!" alt=""><b v-else>{{ game.away_ref[0] }}</b><strong>{{ gameName(game,'away') }}</strong></span></div></button></div>
        </section>
        <section v-else-if="tab==='fixture'" id="public-position-fixture-panel" role="tabpanel" aria-labelledby="public-position-fixture-tab">
          <div class="public-subtabs" role="group" aria-label="Vista de fixture"><button type="button" :aria-pressed="fixtureTab==='dates'" @click="fixtureTab='dates'">Fechas</button><button type="button" :aria-pressed="fixtureTab==='days'" @click="fixtureTab='days'">Jornadas</button></div>
          <template v-if="fixtureTab==='dates'"><div class="public-pills" role="group" aria-label="Fecha deportiva"><button v-for="round in rounds" :key="round" type="button" :aria-pressed="selectedRound===round" @click="selectedRound=round;($event.currentTarget as HTMLElement).scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'})">{{ roundLabel(round) }}</button></div><h2>{{ roundTitle(selectedRound) }}</h2><div v-for="game in roundGames" :key="game.code" class="public-fixture-row is-date"><small>{{ game.jornada_no?`J${game.jornada_no}`:'J1/J2' }}<span>{{ gameDate(game) }}</span></small><strong>{{ gameName(game,'home') }}</strong><em>{{ result(game) }}</em><strong>{{ gameName(game,'away') }}</strong></div></template>
          <template v-else><div class="public-pills" role="group" aria-label="Jornada"><button v-for="day in days" :key="day" type="button" :aria-pressed="selectedDay===day" @click="selectedDay=day;($event.currentTarget as HTMLElement).scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'})">{{ day===0?'J1/J2':`J${day}` }}</button></div><h2>{{ dayTitle(selectedDay) }} <small>{{ dayDate(selectedDay) }}</small></h2><div v-if="!dayGames.length" class="public-hint">Aún sin partidos asignados.</div><div v-for="game in dayGames" :key="game.code" class="public-fixture-row"><small>{{ roundTitle(game.sporting_round) }}</small><strong>{{ gameName(game,'home') }}</strong><em>{{ result(game) }}</em><strong>{{ gameName(game,'away') }}</strong></div><button v-for="nearby in nearbyDays" :key="nearby" type="button" class="public-adjacent" @click="selectedDay=nearby"><span>J{{ nearby }} · {{ dayDate(nearby) }}</span><strong v-for="game in allGames.filter(item=>item.jornada_no===nearby)" :key="game.code">{{ gameName(game,'home') }} – {{ gameName(game,'away') }}</strong><Icon name="arrow" /></button></template>
        </section>
        <section v-else-if="tab==='classification'" id="public-position-classification-panel" role="tabpanel" aria-labelledby="public-position-classification-tab">
          <div class="public-subtabs" role="group" aria-label="Etapa de clasificación"><button v-for="item in [{key:'groups',label:'Grupos'},{key:'quarterfinals',label:'Cuartos'},{key:'quadrangular',label:'Finales'},{key:'general',label:'Tabla general'}]" :key="item.key" type="button" :aria-pressed="classificationTab===item.key" @click="classificationTab=item.key">{{ item.label }}</button></div>
          <template v-if="classificationTab==='groups'"><div class="public-subtabs minor" role="group" aria-label="Elegir grupo"><button v-for="group in ['A','B'] as const" :key="group" type="button" :aria-pressed="groupTab===group" @click="groupTab=group">Grupo {{ group }}</button></div><template v-if="competition?.competition?.official.groups"><div v-for="row in rows(groupTab==='A'?competition.competition.groupA:competition.competition.groupB)" :key="row.id" class="public-table-row"><b>{{ row.unresolved?'=':row.position }}</b><img v-if="crest(byEntry.get(row.id))" :src="crest(byEntry.get(row.id))!" alt=""><span v-else class="public-mark">{{ groupTab }}</span><strong>{{ byEntry.get(row.id)?.team_name||'Por definir' }}</strong><small>{{ row.stats?.played }} PJ</small><b>{{ row.stats?.points }}</b></div></template><template v-else><div v-for="slot in current.snapshot.slots.filter(item=>item.slot_code.startsWith(groupTab))" :key="slot.slot_code" class="public-table-row"><b>{{ slot.slot_code }}</b><img v-if="crest(slot)" :src="crest(slot)!" alt=""><span v-else class="public-mark">{{ groupTab }}</span><strong>{{ slot.team_name||'Por sortear' }}</strong><small>— PJ</small><b>—</b></div></template></template>
          <template v-else-if="classificationTab==='general'"><template v-if="competition?.competition?.official.groups"><div v-for="row in rows(competition.competition.general)" :key="row.id" class="public-table-row"><b>{{ row.unresolved?'=':row.position }}</b><img v-if="crest(byEntry.get(row.id))" :src="crest(byEntry.get(row.id))!" alt=""><span v-else class="public-mark">•</span><strong>{{ byEntry.get(row.id)?.team_name||'Por definir' }}</strong><small>{{ row.stats?.played }} PJ</small><b>{{ row.stats?.points }}</b></div></template><template v-else><div v-for="slot in current.snapshot.slots" :key="slot.slot_code" class="public-table-row"><b>—</b><img v-if="crest(slot)" :src="crest(slot)!" alt=""><span v-else class="public-mark">{{ slot.slot_code[0] }}</span><strong>{{ slot.team_name||slot.slot_code+' · Por sortear' }}</strong><small>— PJ</small><b>—</b></div></template></template>
          <template v-else-if="classificationTab==='quarterfinals'"><div v-for="game in allGames.filter(item=>item.stage==='quarterfinal')" :key="game.code" class="public-stage"><small>Llave {{ game.code.slice(2) }} · J{{ game.jornada_no }}</small><strong>{{ gameName(game,'home') }} <em>{{ result(game) }}</em> {{ gameName(game,'away') }}</strong><small v-if="results.get(game.code)?.homeGoals===results.get(game.code)?.awayGoals&&results.get(game.code)?.homePenalties!==results.get(game.code)?.awayPenalties">Penales {{ results.get(game.code)?.homePenalties }} : {{ results.get(game.code)?.awayPenalties }}</small><button v-if="matches.has(game.code)" type="button" @click="openMatch(game.code)">Ver partido ›</button></div></template>
          <template v-else><div v-if="competition?.competition?.final&&competition.competition.official.quadrangular"><div v-for="row in rows(competition.competition.final)" :key="row.id" class="public-table-row"><b>{{ row.unresolved?'=':row.position }}</b><img v-if="crest(byEntry.get(row.id))" :src="crest(byEntry.get(row.id))!" alt=""><span v-else class="public-mark">•</span><strong>{{ byEntry.get(row.id)?.team_name||'Por definir' }}</strong><small>{{ row.stats?.played }} PJ</small><b>{{ row.stats?.points }}</b></div></div><div v-else><div v-for="seed in [1,2,3,4]" :key="seed" class="public-table-row"><b>{{ seed }}</b><span class="public-mark">•</span><strong>Por definir</strong><small>— PJ</small><b>—</b></div></div><div v-for="game in allGames.filter(item=>item.stage==='quadrangular')" :key="game.code" class="public-stage"><small>{{ roundTitle(game.sporting_round) }} · J{{ game.jornada_no }}</small><strong>{{ gameName(game,'home') }} <em>{{ result(game) }}</em> {{ gameName(game,'away') }}</strong><button v-if="matches.has(game.code)" type="button" @click="openMatch(game.code)">Ver partido ›</button></div><div v-if="competition?.titleExtra?.decision==='extra'" class="public-stage"><small>Partido extra</small><strong>{{ byEntry.get(competition.titleExtra.homeEntryId||'')?.team_name }} <em>{{ competition.titleExtra.score?`${competition.titleExtra.score.home} : ${competition.titleExtra.score.away}`:'–' }}</em> {{ byEntry.get(competition.titleExtra.awayEntryId||'')?.team_name }}</strong><small v-if="competition.titleExtra.score?.home===competition.titleExtra.score?.away&&competition.titleExtra.score?.homePenalties!==competition.titleExtra.score?.awayPenalties">Penales {{ competition.titleExtra.score?.homePenalties }} : {{ competition.titleExtra.score?.awayPenalties }}</small></div></template>
        </section>
        <section v-else-if="tab==='scorers'" id="public-position-scorers-panel" role="tabpanel" aria-labelledby="public-position-scorers-tab"><div v-if="!scorers.length" class="public-hint">Aún sin goles registrados.</div><div v-for="(player,index) in scorers" :key="player.registrationId" class="public-stat-row"><b>{{ index+1 }}</b><strong>{{ player.name }}<small>{{ byEntry.get(player.entryId)?.team_name }}</small></strong><b>⚽ {{ player.goals }}</b></div></section>
        <section v-else-if="tab==='defense'" id="public-position-defense-panel" role="tabpanel" aria-labelledby="public-position-defense-tab"><div v-if="!defense.length" class="public-hint">Aún sin partidos oficiales.</div><div v-for="(team,index) in defense" :key="team.entryId" class="public-stat-row"><b>{{ index+1 }}</b><strong>{{ byEntry.get(team.entryId)?.team_name }}<small>{{ team.played }} PJ</small></strong><b>{{ team.goalsAgainst }} GC</b></div></section>
        <section v-else id="public-position-teams-panel" class="public-team-list" role="tabpanel" aria-labelledby="public-position-teams-tab"><button v-for="team in teams" :key="team.entry_id" type="button" class="public-team" @click="openTeam(team)"><img v-if="crest(team)" :src="crest(team)!" alt=""><span v-else class="public-mark">{{ team.team_name.slice(0,2).toUpperCase() }}</span><strong>{{ team.team_name }}</strong><Icon name="arrow" /></button></section>
      </main>
    </template>
    <section v-if="selectedMatch" class="public-detail"><button type="button" class="public-detail-close" @click="closeMatch">‹ Partidos</button><div class="public-score"><small>{{ selectedMatch.result?'FINAL':'PARTIDO' }}</small><div><strong>{{ selectedMatch.home_name }}</strong><b>{{ selectedMatch.result?.score.home ?? '–' }} : {{ selectedMatch.result?.score.away ?? '–' }}</b><strong>{{ selectedMatch.away_name }}</strong></div><p v-if="selectedMatch.result&&(selectedMatch.result.shootout.home||selectedMatch.result.shootout.away)">Penales {{ selectedMatch.result.shootout.home }} : {{ selectedMatch.result.shootout.away }}</p></div><div class="public-events"><h2>Eventos</h2><div v-if="!selectedMatch.result?.events.length" class="public-hint">Sin eventos registrados.</div><div v-for="event in selectedMatch.result?.events||[]" :key="event.id"><span>{{ event.kind==='goal'||event.kind==='penalty'?'⚽':event.kind==='penalty_miss'?'⚽×':event.kind==='own_goal'?'⚽↩':event.kind.includes('yellow')?'🟨':event.kind==='red'?'🟥':'•' }}</span><strong>{{ event.name }}</strong><small>{{ event.period||'' }} {{ event.cardLabel||'' }}</small></div></div></section>
    <section v-else-if="selectedGame" class="public-detail"><button type="button" class="public-detail-close" @click="selectedGame=null">‹ Partidos</button><div class="public-score"><small>{{ roundTitle(selectedGame.sporting_round) }} · {{ selectedGame.jornada_no?`J${selectedGame.jornada_no}`:'J1/J2 por definir' }}</small><div><strong><img v-if="crest(gameTeam(selectedGame,'home'))" :src="crest(gameTeam(selectedGame,'home'))!" alt="">{{ gameName(selectedGame,'home') }}</strong><b>–</b><strong><img v-if="crest(gameTeam(selectedGame,'away'))" :src="crest(gameTeam(selectedGame,'away'))!" alt="">{{ gameName(selectedGame,'away') }}</strong></div><p>{{ gameDate(selectedGame) }}</p></div><div class="public-events"><h2>Partido por programar</h2></div></section>
    <section v-else-if="selectedTeam" class="public-detail"><button type="button" class="public-detail-close" @click="selectedTeam=null">‹ Equipos</button><div class="public-team-hero"><img v-if="crest(selectedTeam)" :src="crest(selectedTeam)!" alt=""><span v-else class="public-mark">{{ selectedTeam.team_name.slice(0,2).toUpperCase() }}</span><h1>{{ selectedTeam.team_name }}</h1></div><div class="public-events"><h2>Jugadores</h2><div v-if="teamLoading" class="public-hint">Cargando…</div><div v-else-if="!teamPlayers.length" class="public-hint">Aún no hay jugadores publicados.</div><div v-for="player in teamPlayers" :key="player.name" class="public-player"><Icon name="users" /><strong>{{ player.name }}</strong></div></div></section>
  </div>
